#!/usr/bin/env python3
"""Generate tables/tab_fullsets.tex: thinking effect on the full held-out IMPPRES some/or sets (300 items per trigger)
in the Yes/No and the three-way format, for every model with a full-set run (E1SF: Qwen3; E1SFX: others). Grey = CI includes 0."""
import re
from pathlib import Path
ROOT = Path(__file__).resolve().parents[1]
V = dict(re.findall(r'\\resdef\{([^}]*)\}\{([^}]*)\}', (ROOT / "build/results_full.tex").read_text()))
ROWS = [("Qwen3-4B", "e1sf", "qwen3-4b"), ("Qwen3-8B", "e1sf", "qwen3-8b"), ("Qwen3-14B", "e1sf", "qwen3-14b"), ("Qwen3-30B-A3B", "e1sf", "qwen3-30b-a3b"), ("Qwen3-32B", "e1sf", "qwen3-32b"), None,
        ("Qwen3.5-0.8B", "e1sfx", "qwen3p5-0p8b"), ("Qwen3.5-2B", "e1sfx", "qwen3p5-2b"), ("Qwen3.5-4B", "e1sfx", "qwen3p5-4b"), ("Qwen3.5-9B", "e1sfx", "qwen3p5-9b"), ("Qwen3.8-27B", "e1sfx", "qwen3p8-27b"), None,
        ("Phi-4-reasoning", "e1sfx", "phi4-reasoning"), ("Phi-4-mini-reasoning", "e1sfx", "phi4-mini-reasoning"), ("R1-Distill-Llama-8B", "e1sfx", "r1distill-llama-8b"),
        ("Skywork-OR1-7B", "e1sfx", "skywork-or1-7b"), ("EXAONE-Deep-7.8B", "e1sfx", "exaone-deep-7p8b"), ("Nemotron-Nano-9B-v2", "e1sfx", "nemotron-nano-9b-v2"),
        ("Granite-3.3-8B", "e1sfx", "granite-3p3-8b"), ("Llama-3.1-Nemotron-Nano-8B", "e1sfx", "llama-nemotron-nano-8b"), ("SmolLM3-3B", "e1sfx", "smollm3-3b"), ("openPangu-Embedded-7B-V1.1", "e1pangu", "openpangu-embedded-7b-v1p1"), ("openPangu-Embedded-7B-model", "e1pangu", "openpangu-embedded-7b-model")]
def cell(pre, m, trig, fmt):
    k = f"{pre}.{m}.a3f-{trig}.{fmt}.nat.dR"
    if k + ".mean" not in V: return r"\na"
    lo, hi = float(V[k + ".lo"]), float(V[k + ".hi"])
    b = f"\\res{{{k}.mean}}{{\\scriptsize\\,[\\res{{{k}.lo}}, \\res{{{k}.hi}}]}}"
    return b if (lo > 0 or hi < 0) else f"\\textcolor{{gray}}{{{b}}}"
out = [r"% GENERATED by tools/make_tab_fullsets.py -- do not edit by hand.", r"\begin{table*}[t]", r"  \centering\small", r"  \setlength{\tabcolsep}{4pt}",
       r"  \begin{tabular}{@{}l cc cc@{}}", r"    \toprule", r"    & \multicolumn{2}{c}{Yes/No inference} & \multicolumn{2}{c}{Three-way choice} \\",
       r"    \cmidrule(lr){2-3}\cmidrule(l){4-5}", r"    Model & \form{some} & \form{or} & \form{some} & \form{or} \\", r"    \midrule"]
for r in ROWS:
    if r is None: out.append(r"    \midrule"); continue
    n, pre, m = r
    out.append(f"    {n} & " + " & ".join([cell(pre, m, "quant", "inf"), cell(pre, m, "conn", "inf"), cell(pre, m, "quant", "nli"), cell(pre, m, "conn", "nli")]) + r" \\")
out += [r"    \bottomrule", r"  \end{tabular}",
        r"  \caption{\textbf{On the full held-out sets, \form{some} and \form{or} turn literal with thinking in both formats in most models.} Change with thinking (pp) [95\% CI], 300 items per trigger; grey: CI includes 0. Some models start near the floor in the three-way format.}",
        r"  \label{tab:fullsets}", r"\end{table*}"]
(ROOT / "tables/tab_fullsets.tex").write_text("\n".join(out) + "\n"); print("wrote tab_fullsets")
